import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"橫渠易說 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"橫渠易說 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/hengqu/036.md","filePath":"classics/hengqu/036.md"}'),l={name:"classics/hengqu/036.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><h3 id="彖曰-大壯-大者壯也-剛以動故壯。-大壯利貞-大者正也-正大而天地之情可見矣。" tabindex="-1">彖曰：大壯，大者壯也，剛以動故壯。“大壯利貞”，大者正也，正大而天地之情可見矣。 <a class="header-anchor" href="#彖曰-大壯-大者壯也-剛以動故壯。-大壯利貞-大者正也-正大而天地之情可見矣。" aria-label="Permalink to “彖曰：大壯，大者壯也，剛以動故壯。“大壯利貞”，大者正也，正大而天地之情可見矣。”">​</a></h3><h3 id="象曰-雷在天上-大壯-君子以非禮弗履。" tabindex="-1">象曰：雷在天上，大壯，君子以非禮弗履。 <a class="header-anchor" href="#象曰-雷在天上-大壯-君子以非禮弗履。" aria-label="Permalink to “象曰：雷在天上，大壯，君子以非禮弗履。”">​</a></h3><p>克己反禮，壯莫甚焉，故易於大壯見之。 克己，下學上達交相養也，下學則必達，達則必上，蓋不行則終何以成德？明則誠矣，誠則明矣，克己要當以理義戰退私己，蓋理乃天德，克己者必有剛強壯健之德乃勝己。“雷在天上，大壯，君子以非禮弗履”。夫酒清人渴而不敢飲，餚乾人飢而不敢食，非強有力者不能人所不能。人所以不能行己者，於其所難者則惰，其異俗者雖易而羞縮。惟心弘則不顧人之非笑，所趨義理耳，視天下莫能移其道。然為之人亦未必怪，正以在己者義理不勝惰與羞縮之病，消則有長，不消則病常在，消盡則是大而化之之謂聖。意思齷齪，無由作事。在古氣節之士冒死以有為，於義未必中，然非有志概者莫能。況吾於義理已明，何為不為？正以不剛。惟大壯乃能克己，蓋君子欲身行之，為事業以教天下。今夫為長者折枝，非不能也，但恥以為屈而不為耳，不顧義理之若何。</p><h3 id="初九-壯於趾-徵兇-有孚。-象曰-壯於趾-其孚窮也。" tabindex="-1">初九，壯於趾，徵兇，有孚。 象曰：“壯於趾”，其孚窮也。 <a class="header-anchor" href="#初九-壯於趾-徵兇-有孚。-象曰-壯於趾-其孚窮也。" aria-label="Permalink to “初九，壯於趾，徵兇，有孚。 象曰：“壯於趾”，其孚窮也。”">​</a></h3><h3 id="九二-貞吉。-象曰-九二貞吉-以中也。" tabindex="-1">九二，貞吉。 象曰：“九二貞吉”，以中也。 <a class="header-anchor" href="#九二-貞吉。-象曰-九二貞吉-以中也。" aria-label="Permalink to “九二，貞吉。 象曰：“九二貞吉”，以中也。”">​</a></h3><h3 id="九三-小人用壯-君子用罔-貞厲。羝羊觸藩-羸其角。-象曰-小人用壯-君子罔也。" tabindex="-1">九三，小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。 象曰：“小人用壯”，君子罔也。 <a class="header-anchor" href="#九三-小人用壯-君子用罔-貞厲。羝羊觸藩-羸其角。-象曰-小人用壯-君子罔也。" aria-label="Permalink to “九三，小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。 象曰：“小人用壯”，君子罔也。”">​</a></h3><p>以陽居陽，正也，然乘下之剛，故危。小人用此而進，如羝羊觸藩以為壯，故多見困，君子知幾則否。藩以喻四、三有應，所之在進而位正理直，小人處之，必以剛動。</p><h3 id="九四-貞吉悔亡。藩決不羸-壯於大輿之輹。-象曰-藩決不羸-尚往也。" tabindex="-1">九四，貞吉悔亡。藩決不羸，壯於大輿之輹。 象曰：“藩決不羸”，尚往也。 <a class="header-anchor" href="#九四-貞吉悔亡。藩決不羸-壯於大輿之輹。-象曰-藩決不羸-尚往也。" aria-label="Permalink to “九四，貞吉悔亡。藩決不羸，壯於大輿之輹。 象曰：“藩決不羸”，尚往也。”">​</a></h3><p>乘剛本有悔，不用其壯，故貞吉。三以四為藩，九四上無陽爻，故曰藩決，壯輿之輹，往無咎也。四能不為陰累，守己以正，則吉而無乘剛之悔，且得眾陽之助以銷陰慝。</p><h3 id="六五-喪羊於易-無悔。-象曰-喪羊於易-位不當也。" tabindex="-1">六五，喪羊於易，無悔。 象曰：“喪羊於易”，位不當也。 <a class="header-anchor" href="#六五-喪羊於易-無悔。-象曰-喪羊於易-位不當也。" aria-label="Permalink to “六五，喪羊於易，無悔。 象曰：“喪羊於易”，位不當也。”">​</a></h3><p>羊外柔而內很，六五以陰處陽，羊喪之象也，能去其內剛，不拒來者，則無悔，故曰“喪羊於易無悔”。履柔危之地，乘壯動之剛，固之必悔者，位非其所堪也。</p><h3 id="上六-羝羊觸藩-不能退-不能遂-無攸利-艱則吉。-象曰-不能退-不能遂-不詳也。-艱則吉-咎不長也。" tabindex="-1">上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。 象曰：“不能退，不能遂”，不詳也。“艱則吉”，咎不長也。 <a class="header-anchor" href="#上六-羝羊觸藩-不能退-不能遂-無攸利-艱則吉。-象曰-不能退-不能遂-不詳也。-艱則吉-咎不長也。" aria-label="Permalink to “上六，羝羊觸藩，不能退，不能遂，無攸利，艱則吉。 象曰：“不能退，不能遂”，不詳也。“艱則吉”，咎不長也。”">​</a></h3><p>剛競用觸則進退皆兇，危懼求全則咎有時而息也。然上六以陰居上，不詳事宜，用壯而觸，故進退不能。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
